//TODO: Split out the dedications-select specific logic into it's own model. We don't need any of that when viewing dedications in the legacies-screen
import { Accessor, createEffect, createMemo, createSignal, on, onCleanup, onMount } from "solid-js";
import { createStore } from "solid-js/store";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";
import { createEngineEvent, useLocalPlayerId } from "#core/ui-next/utilities/game-core-utilities.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

import {
	addAvailableCard,
	getLegacyCardStyling,
	getLegacyTypeFromCardID,
	getStylingFromTag,
	isCrisis,
	markCompletedDeck,
	parseCardText,
	removeAvailableCard,
	selectCapital,
} from "#base/ui-next/screens/legacies/legacies-support.js";

export interface DedicationCardItem {
	id: string;
	containerID: string;
	type: string;
	description: string;
	traitIcon?: string;
	descriptionBG?: string;
}

export interface DedicationData {
	id: string;
	containerID: string;
	type: string;
	title: string;
	description: string;
	isDisabled: boolean;
	traitIcon?: string;
	descriptionBG?: string;
	filterOptions?: string[];
}

export enum DedicationsFilterOptions {
	ALL = "ALL",
	DEFAULT = "DEFAULT",
	CULTURAL = "CULTURAL",
	DIPLOMATIC = "DIPLOMATIC",
	ECONOMIC = "ECONOMIC",
	EXPANSIONIST = "EXPANSIONIST",
	MILITARISTIC = "MILITARISTIC",
	SCIENTIFIC = "SCIENTIFIC",
	CRISIS = "CRISIS",
}

const CreateDedicationsModel = () => {
	const SMALL_SCREEN_MODE_MAX_HEIGHT = 800;
	const SMALL_SCREEN_MODE_MAX_WIDTH = 1000;

	const DEDICATIONS_SLOT_IDS = ["Slot1", "Slot2", "Slot3"];
	const DEDICATIONS_AVAILABLE_ID = "Available";

	const isSmallScreen = createMemo(() => {
		const isMobileViewExperience = UI.getViewExperience() == UIViewExperience.Mobile;
		const layoutModel = LayoutModel.get();
		return (
			isMobileViewExperience ||
			layoutModel.screenHeight() <= Layout.pixelsToScreenPixels(SMALL_SCREEN_MODE_MAX_HEIGHT) ||
			layoutModel.screenWidth() <= Layout.pixelsToScreenPixels(SMALL_SCREEN_MODE_MAX_WIDTH)
		);
	});

	const localPlayerID: Accessor<PlayerId> = useLocalPlayerId();
	const playerLegacyCompleted = createEngineEvent("PlayerLegacyCompleted");

	const [selectedDedicationFilter, setSelectedDedicationFilter] = createSignal<DedicationsFilterOptions | undefined>(
		DedicationsFilterOptions.ALL,
	);
	const [selectedCapital, setSelectedCapital] = createSignal<ComponentID | undefined>(
		getCapital() !== null ? getCapital()!.id : undefined,
	);

	const isAdvancedStart = createMemo(
		() =>
			GameInfo.Ages.lookup(Game.age)?.AgeType != "AGE_ANTIQUITY" && Configuration.getGame().previousAgeCount == 0,
	);

	const [state, setState] = createStore({
		assignedItems: [
			...DEDICATIONS_SLOT_IDS.map((slotID) => {
				return { id: "Empty", containerID: slotID };
			}),
		],
		containers: [
			...DEDICATIONS_SLOT_IDS.map((slotID) => {
				return { id: slotID, maxCount: 1, canSwap: true };
			}),
			{ id: DEDICATIONS_AVAILABLE_ID, maxCount: -1, canSwap: false },
		],
		items: populateDedicationData(),
		legacies: populateLegaciesData(),
		selectedItems: getSelectedItems(),
	});
	const pendingToAdd: string[] = [];
	const isDeckFull = createMemo(() => state.selectedItems.length == DEDICATIONS_SLOT_IDS.length);

	onMount(() => {
		autoSlotSelectedItems();

		if (isAdvancedStart()) {
			engine.on("AdvancedStartCardAdded", setSelectedItems);
			engine.on("AdvancedStartCardRemoved", setSelectedItems);
		}
	});

	onCleanup(() => {
		if (isAdvancedStart()) {
			engine.off("AdvancedStartCardAdded", setSelectedItems);
			engine.off("AdvancedStartCardRemoved", setSelectedItems);
		}
	});

	createEffect(() => {
		if (localPlayerID() != PlayerIds.NO_PLAYER) {
			// if it's a valid player, update the model
			setState("items", populateDedicationData());
			setState("legacies", populateLegaciesData());
			setState("selectedItems", getSelectedItems());
		}
	});

	createEffect(
		on(playerLegacyCompleted, (data: PlayerLegacyComplete_EventData) => {
			if (!data) {
				return;
			}
			const legacyDef = GameInfo.Legacies.lookup(data.legacy);
			if (!legacyDef) {
				console.error(
					"dedications-model: Unable to find triumph definition for triumph of type: " + data.legacy,
				);
				return;
			}

			if (data.player != localPlayerID()) {
				return;
			}

			setState("legacies", populateLegaciesData());
		}),
	);

	const updatePendingCards = () => {
		pendingToAdd.forEach((item) => {
			if (!isItemInCardDeck(item)) {
				addAvailableCard(item);
			}
		});
		pendingToAdd.length = 0;
	};

	createEffect(() => {
		const slotItems = state.items.filter((item) => DEDICATIONS_SLOT_IDS.includes(item.containerID));
		const availableItems = state.items.filter((item) => item.containerID == DEDICATIONS_AVAILABLE_ID);

		slotItems.forEach((slotItem) => {
			setState("assignedItems", (item) => item.containerID == slotItem.containerID, "id", slotItem.id);
			// Add to gamecore deck
			if (!isItemInCardDeck(slotItem.id)) {
				if (isDeckFull()) {
					// it's posible the deck hasn't updated yet, add to the pending list until another card is removed
					pendingToAdd.push(slotItem.id);
				} else {
					addAvailableCard(slotItem.id);
				}
			}
		});

		availableItems.forEach((availableItem) => {
			setState("assignedItems", (item) => item.id == availableItem.id, "id", "Empty");
			// Remove from gamecore deck
			if (isItemInCardDeck(availableItem.id)) {
				removeAvailableCard(availableItem.id);
				updatePendingCards();
			}
		});

		items(DEDICATIONS_AVAILABLE_ID).forEach((item) => {
			// Update the disabled state depending on interaction
			setState("items", (i) => i.id == item.id, "isDisabled", isCapitalCardSlotted(item.id));
		});
	});

	function getSelectedItems() {
		const advancedStart = getAdvancedStart();
		if (!advancedStart) {
			return [];
		}
		// Get current added cards and equip them
		const selectedCards: AdvancedStartCard[] = advancedStart.getCards();
		return selectedCards;
	}

	function autoSlotSelectedItems() {
		if (isAdvancedStart()) {
			return;
		}
		state.selectedItems.forEach((item) => {
			if (canAutoSlotItem(item.info.id)) {
				autoSlotItem(item.info.id);
			}
		});
	}

	function setSelectedItems() {
		setState("selectedItems", getSelectedItems());
	}

	function updateSelectedItems() {
		const selectedItems = getSelectedItems();
		const modelItems = state.selectedItems;

		if (selectedItems.length == 0 && modelItems.length == 0) {
			// No items assigned yet
			return;
		}

		// Get difference between model state and the gamecore state.
		// items selected but not in model
		const selectedFiltered = selectedItems.filter(
			(selected) => !modelItems.some((item) => selected.info.id == item.info.id),
		);
		// items in model but not selected
		const modelFiltered = modelItems.filter(
			(selected) => !selectedItems.some((item) => selected.info.id == item.info.id),
		);

		// Auto slot the new selected items
		selectedFiltered.forEach((item) => {
			if (canAutoSlotItem(item.info.id)) {
				autoSlotItem(item.info.id);
			}
		});

		// Unequip the non selected items
		modelFiltered.forEach((item) => {
			unEquipItem(item.info.id);
		});

		// Update state for the selected items.
		setState("selectedItems", selectedItems);
	}

	/**
	 * @param itemID item to check
	 * @returns Checks if an item is a capital card and if there's currently one slotted
	 */
	function isCapitalCardSlotted(itemID: string): boolean {
		// is the item we want to check a change capital card?
		if (itemID.includes("CHANGE_CAPITAL")) {
			return DEDICATIONS_SLOT_IDS.some((id) => items(id).some((item) => item.id.includes("CHANGE_CAPITAL")));
		}
		return false;
	}

	/**
	 * @param itemID item to check
	 * @returns Checks if an item is a capital card and if there's currently one in deck
	 */
	function isCapitalCardInDeck(itemID: string): boolean {
		if (itemID.includes("CHANGE_CAPITAL")) {
			return getSelectedItems().some((item) => item.info.id.includes("CHANGE_CAPITAL"));
		}
		return false;
	}

	function getAdvancedStart() {
		if (
			GameContext.localObserverID == PlayerIds.NO_PLAYER ||
			GameContext.localObserverID == PlayerIds.OBSERVER_ID ||
			Autoplay.isActive
		) {
			return null;
		}

		const localPlayer: PlayerLibrary | null = Players.get(localPlayerID());
		if (!localPlayer) {
			console.error(`dedications-model: Failed to retrieve PlayerLibrary for Player ${localPlayerID()}`);
			return null;
		}

		const playerAdvancedStart: PlayerAdvancedStart | undefined = localPlayer.AdvancedStart;
		if (!playerAdvancedStart) {
			console.error(`dedications-model: Failed to retrieve PlayerAdvancedStart for Player ${localPlayerID()}`);
			return null;
		}

		return playerAdvancedStart;
	}

	function populateDedicationData(): DedicationData[] {
		const allDedicationsData: DedicationData[] = [];

		const advancedStart = getAdvancedStart();
		if (!advancedStart) {
			return [];
		}

		for (const cardInfo of advancedStart.getAvailableCards()) {
			allDedicationsData.push(createDedicationData(cardInfo));
		}

		return allDedicationsData;
	}

	function populateLegaciesData() {
		const allLegacyData: DedicationData[] = [];

		const playerLegacies = Players.get(localPlayerID())?.Legacies;
		if (!playerLegacies) {
			return [];
		}

		GameInfo.Legacies.forEach((triumph) => {
			if (!playerLegacies.isValidLegacy(triumph.LegacyType)) {
				return;
			}

			if (triumph.MajorLegacy && playerLegacies.isTriggered(triumph.LegacyType)) {
				allLegacyData.push(createLegacyData(triumph));
			}
		});

		return allLegacyData;
	}

	function createLegacyData(legacyInfo: LegacyDefinition): DedicationData {
		const { tagType, traitIcon, descriptionBG } = getLegacyCardStyling(legacyInfo.LegacyType);

		const legacyData: DedicationData = {
			containerID: DEDICATIONS_AVAILABLE_ID,
			id: legacyInfo.LegacyType,
			type: legacyInfo.LegacyType,
			title: Locale.compose(legacyInfo.Name),
			description: parseCardText(legacyInfo.Description),
			traitIcon: traitIcon,
			descriptionBG: descriptionBG,
			isDisabled: isCapitalCardInDeck(legacyInfo.LegacyType),
			filterOptions: [DedicationsFilterOptions.ALL, tagType],
		};

		return legacyData;
	}

	function createDedicationData(cardInfo: AgeCardInfo): DedicationData {
		let { tagType, traitIcon, descriptionBG } = getLegacyCardStyling(getLegacyTypeFromCardID(cardInfo.id));

		if (tagType.length == 0 && isCrisis(cardInfo)) {
			tagType = "CRISIS";
			traitIcon = getStylingFromTag("CRISIS").traitIcon;
			descriptionBG = getStylingFromTag("CRISIS").descriptionBG;
		}

		const legacyData: DedicationData = {
			containerID: DEDICATIONS_AVAILABLE_ID,
			id: cardInfo.id,
			type: cardInfo.id,
			title: Locale.compose(cardInfo.name),
			description: parseCardText(cardInfo.description),
			traitIcon: traitIcon,
			descriptionBG: descriptionBG,
			isDisabled: isCapitalCardInDeck(cardInfo.id),
			filterOptions: [DedicationsFilterOptions.ALL, tagType != "" ? tagType : DedicationsFilterOptions.DEFAULT],
		};

		return legacyData;
	}

	function contains(itemID: string, containerID: string) {
		const item = state.items.find((item) => item.id == itemID);
		return item && item.containerID == containerID;
	}

	function canContain(containerID: string) {
		const container = state.containers.find((c) => c.id == containerID);
		if (container == null) {
			return false;
		}

		if (container.canSwap) {
			return true;
		}

		if (container.maxCount != -1) {
			let count = 0;
			for (const item of state.items) {
				if (item.containerID == containerID) {
					count++;
				}
			}

			if (count >= container.maxCount) {
				return false;
			}
		}

		return true;
	}

	function item(itemID: string) {
		return state.items.find((item) => item.id == itemID);
	}

	function items(containerID: string) {
		return state.items.filter((item) => item.containerID == containerID);
	}

	function isItemInCardDeck(itemID: string): boolean {
		const advancedStart = getAdvancedStart();
		if (!advancedStart) {
			return false;
		}
		const selectedCards: AdvancedStartCard[] = advancedStart.getCards();
		return selectedCards.some((card) => card.info.id == itemID);
	}

	function equipItem(itemID: string, containerID: string) {
		const item = state.items.find((item) => item.id == itemID);
		const container = state.containers.find((c) => c.id == containerID);

		// No item? do nothing.
		if (item == null) {
			return;
		}

		// No container? do nothing.
		if (container == null) {
			return;
		}

		// Already in container, do nothing.
		if (item.containerID == containerID) {
			return;
		}

		// If the container cannot hold it, do nothing.
		if (!canContain(containerID) || item.isDisabled) {
			return;
		}

		setState("items", (item) => item.id == itemID, "containerID", containerID);
	}

	function unEquipItem(itemID: string) {
		const item = state.items.find((item) => item.id == itemID);

		// No item? do nothing.
		if (item == null) {
			return;
		}

		// Item already in cards container? do nothing.
		if (item.containerID == "Available") {
			return;
		}

		setState("items", (item) => item.id == itemID, "containerID", "Available");
	}

	function swapItem(itemID: string, containerID: string) {
		const container = state.containers.find((c) => c.id == containerID);
		if (container && container.maxCount > 1) {
			return false;
		}

		const itemInContainer: DedicationData = items(containerID)[0];
		const containerFromItem: string | undefined = state.assignedItems.find((i) => i.id == itemID)?.containerID;

		if (containerFromItem && DEDICATIONS_SLOT_IDS.includes(containerFromItem)) {
			equipItem(itemID, containerID);
			equipItem(itemInContainer.id, containerFromItem);
		} else if (itemInContainer && contains(itemInContainer.id, containerID)) {
			unEquipItem(itemInContainer.id);
			equipItem(itemID, containerID);
			return true;
		}

		return false;
	}

	function hasItem(containerID: string): boolean {
		const container = state.containers.find((c) => c.id == containerID);
		if (container && container.maxCount != 1) {
			return false;
		}

		return items(containerID).length > 0;
	}

	function canAutoSlotItem(itemID: string) {
		const item = state.items.find((e) => e.id == itemID);
		if (item) {
			// Is it already in a slot?
			if (DEDICATIONS_SLOT_IDS.includes(item.containerID)) {
				return false;
			}

			// Is the slot empty and can this item slot into it?
			for (const containerID of DEDICATIONS_SLOT_IDS) {
				if (state.items.every((e) => e.containerID != containerID) && canContain(containerID)) {
					return true;
				}
			}
		}

		return false;
	}

	function autoSlotItem(itemID: string) {
		const item = state.items.find((e) => e.id == itemID);
		if (item) {
			// Is it already in a slot?
			if (DEDICATIONS_SLOT_IDS.includes(item.containerID)) {
				return;
			}

			// Is the slot empty and can this item slot into it?
			for (const containerID of DEDICATIONS_SLOT_IDS) {
				if (state.items.every((e) => e.containerID != containerID) && canContain(containerID)) {
					equipItem(itemID, containerID);
					return;
				}
			}
		}
	}

	function confirmDeck() {
		if (pendingToAdd.length > 0) {
			return;
		}
		// If we've confirmed our deck and we have no placeable effects apply all instant effects
		applyEffects();
		// Set the selected capital city from the dropdown
		const player = Players.get(localPlayerID());
		const changeName = player ? player.previousAgeCivilizationType != player.civilizationType : false;
		if (selectedCapital() !== undefined) {
			selectCapital(selectedCapital()!, changeName);
		}
		// Finish setting the cards in deck
		markCompletedDeck();
	}

	function applyEffects() {
		const selectedCards: AdvancedStartCard[] = getSelectedItems();
		for (const card of selectedCards) {
			for (const effect of card.info.effects) {
				// Use the effect the correct number of times
				for (let i = 0; i < effect.amount; i++) {
					const args: object = { ID: effect.id };
					const result: OperationResult = Game.PlayerOperations.canStart(
						localPlayerID(),
						PlayerOperationTypes.ADVANCED_START_USE_EFFECT,
						args,
						false,
					);
					if (result.Success) {
						Game.PlayerOperations.sendRequest(
							localPlayerID(),
							PlayerOperationTypes.ADVANCED_START_USE_EFFECT,
							args,
						);
					} else {
						console.error(`dedications-model: Failed to apply effect when confirm deck: ${effect.id}`);
					}
				}
			}
		}
	}

	function isPlacementComplete() {
		const advancedStart = getAdvancedStart();
		if (!advancedStart) {
			return false;
		}
		return advancedStart.getPlacementComplete();
	}

	function getAllCapitals(): City[] {
		const playerCities = Players.get(localPlayerID())?.Cities;
		if (!playerCities) {
			return [];
		}

		const capitalIDs: ComponentID[] = playerCities.getPotentialSwitchCapitalCityIds();
		const capitals = capitalIDs.map((id) => Cities.get(id)).filter((city) => city != null);
		// Add the current capital to the options
		capitals.push(getCapital()!);
		return capitals;
	}

	function getSelectedCapitalCity(): City | null {
		const currentCapital: ComponentID | undefined = selectedCapital();
		return currentCapital ? Cities.get(currentCapital) : getCapital();
	}

	function getCapital(): City | null {
		const playerCities = Players.get(localPlayerID())?.Cities;
		if (!playerCities) {
			return null;
		}

		return playerCities.getCapital();
	}

	return {
		DEDICATIONS_SLOT_IDS,
		DEDICATIONS_AVAILABLE_ID,
		state,
		setState,
		contains,
		canContain,
		item,
		items,
		equipItem,
		unEquipItem,
		swapItem,
		hasItem,
		canAutoSlotItem,
		autoSlotItem,
		updateSelectedItems,
		applyEffects,
		confirmDeck,
		isPlacementComplete,
		selectedDedicationFilter,
		setSelectedDedicationFilter,
		selectedCapital,
		setSelectedCapital,
		getAllCapitals,
		getSelectedCapitalCity,
		isSmallScreen,
	};
};

export const DedicationsModel = ModelRegistry.register(
	"DedicationsModel",
	ModelLifecycle.SharedInstance,
	CreateDedicationsModel,
);
